using Essco.Application.HumanResources;using Essco.Application.Security;using Essco.Domain.HumanResources;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;namespace Essco.Web.Pages.Employees;[Authorize(Policy=Permissions.EmployeesView)]public sealed class DetailModel(EmployeeService service):PageModel{public new EmployeeFile File{get;private set;}=null!;public async Task<IActionResult>OnGetAsync(string id,CancellationToken t){var x=await service.GetAsync(id,t);if(x is null)return NotFound();File=x;return Page();}}
